changeSet.sql:
CREATE TABLE payroll.payslips ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, payroll_run_id UUID NOT NULL REFERENCES payroll.payroll_runs(id) ON DELETE CASCADE, employee_id UUID NOT NULL, employment_contract_id UUID, working_days INT, present_days INT, absent_days INT, leave_days NUMERIC(5,2), late_count INT, overtime_hours NUMERIC(6,2), gross_amount NUMERIC(18,2) NOT NULL, taxable_amount NUMERIC(18,2) NOT NULL, pph21_amount NUMERIC(18,2) NOT NULL DEFAULT 0, bpjs_employee NUMERIC(18,2) NOT NULL DEFAULT 0, bpjs_employer NUMERIC(18,2) NOT NULL DEFAULT 0, other_deductions NUMERIC(18,2) NOT NULL DEFAULT 0, net_amount NUMERIC(18,2) NOT NULL, payment_method VARCHAR(20) DEFAULT 'bank_transfer', bank_code VARCHAR(10), bank_account_no_encrypted BYTEA, payslip_pdf_url TEXT, is_sent BOOLEAN NOT NULL DEFAULT FALSE, sent_at TIMESTAMPTZ, ptkp_code VARCHAR(10), ter_category VARCHAR(5), calculation_snapshot JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (payroll_run_id, employee_id) ); CREATE INDEX idx_payslip_emp_created ON payroll.payslips(employee_id, created_at DESC);
CREATE TABLE payroll.payslip_lines ( id UUID NOT NULL DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, payslip_id UUID NOT NULL, salary_component_id UUID NOT NULL REFERENCES payroll.salary_components(id), category VARCHAR(20) NOT NULL, amount NUMERIC(18,2) NOT NULL, quantity NUMERIC(10,2), rate NUMERIC(18,2), notes TEXT, display_order INT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (id, created_at) ) PARTITION BY RANGE (created_at);
CREATE TABLE payroll.payslip_lines_2026 PARTITION OF payroll.payslip_lines FOR VALUES FROM ('2026-01-01') TO ('2027-01-01'); CREATE TABLE payroll.payslip_lines_2027 PARTITION OF payroll.payslip_lines FOR VALUES FROM ('2027-01-01') TO ('2028-01-01'); CREATE INDEX idx_lines_payslip ON payroll.payslip_lines(payslip_id);

DO $$ DECLARE tbl TEXT; BEGIN
  FOR tbl IN SELECT table_name FROM information_schema.tables
    WHERE table_schema='payroll' AND table_name NOT LIKE '%_20%'
  LOOP
    EXECUTE format('ALTER TABLE payroll.%I ENABLE ROW LEVEL SECURITY;', tbl);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON payroll.%I USING (tenant_id = COALESCE(NULLIF(current_setting(''app.current_tenant_id'', true), ''''), ''00000000-0000-0000-0000-000000000000'')::uuid);',
      tbl);
  END LOOP;
END $$;
